public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;

    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

    for (char c : s.toCharArray()) {
        if (c >= 'a') minHeap.offer(c);
        else maxHeap.offer(c);
    }

    boolean done = false;
    while (!done) {
        done = true;
        pickChar(minHeap, result);
        done &= minHeap.isEmpty();
        pickChar(maxHeap, result);
        done &= maxHeap.isEmpty();
    }

    return result.toString();
}

private void pickChar(PriorityQueue<Character> pq, StringBuilder sb) {
    if (!pq.isEmpty()) {
        char c = pq.poll();
        sb.append(c);
        if (pq.peek() != c) pickChar(pq, sb);
    }
}
