public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;
    List<Integer> fibs = buildFibs(k);
    int counter = 0;
    for (int fib : fibs) {
        while (k >= fib) {
            k -= fib;
            counter++;
        }
        if (k == 0) return counter;
    }
    return -1;
}

private List<Integer> buildFibs(int k) {
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int temp = b;
        b += a;
        a = temp;
    }
    return fibs;
}
