public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] maxArea = new int[n];

    int leftMax = 0;
    for (int i = 0; i < n; i++) {
        while (!leftMax.isEmpty() && heights[i] <= heights[leftMax.peek()]) {
            leftMax.pop();
        }
        if (leftMax.isEmpty()) {
            left[i] = 0;
        } else {
            left[i] = leftMax.peek();
        }
        leftMax.push(i);
    }

    int rightMax = 0;
    for (int i = n - 1; i >= 0; i--) {
        while (!rightMax.isEmpty() && heights[i] <= heights[rightMax.peek()]) {
            rightMax.pop();
        }
        if (rightMax.isEmpty()) {
            right[i] = n;
        } else {
            right[i] = rightMax.peek();
        }
        rightMax.push(i);
    }

    int max = 0;
    for (int i = 0; i < n; i++) {
        maxArea[i] = (right[i] - left[i] - 1) * heights[i];
        max = Math.max(max, maxArea[i]);
    }

    return max;
}
