public static int findNthUglyNumber(int n) {
    int ugly = 0, two = 1, three = 1, five = 1, i = 0, j = 0, k = 0;
    List<Integer> uglyNumbers = new ArrayList<>();
    uglyNumbers.add(1);

    while (uglyNumbers.size() < n) {
        int nextUgly = Math.min(two * ugly, Math.min(three * ugly, five * ugly));
        uglyNumbers.add(nextUgly);
        if (nextUgly == two * ugly) {
            two = uglyNumbers.get(++i) * 2;
        }
        if (nextUgly == three * ugly) {
            three = uglyNumbers.get(++j) * 3;
        }
        if (nextUgly == five * ugly) {
            five = uglyNumbers.get(++k) * 5;
        }
    }

    return uglyNumbers.get(n - 1);
}
